    func listMyWords(_ input: Operations.ListMyWords.Input) async throws -> Operations.ListMyWords.Output
    /// Награды — полученные и прогресс к остальным
    ///
    /// Все награды набора по порядку показа: полученные — с днём получения, остальные — с прогрессом («3 из 7»).
    /// Пересчитываются из истории ученика (уроки, серия, цель дня, «Мой словарь», голоса, места тропы) по правилам
    /// векторов `contracts/test-vectors/achievements`. Новая награда приходит и в итоге урока (`newAchievements`).
    ///
    ///
    /// - Remark: HTTP `GET /api/v1/me/achievements`.
    /// - Remark: Generated from `#/paths//api/v1/me/achievements/get(listMyAchievements)`.
    func listMyAchievements(_ input: Operations.ListMyAchievements.Input) async throws -> Operations.ListMyAchievements.Output
