    func getCurrentLeague(_ input: Operations.GetCurrentLeague.Input) async throws -> Operations.GetCurrentLeague.Output
    /// Итог недели лиги просмотрен
    ///
    /// Отмечает итог недели `weekStart` просмотренным — экран «Новая лига» больше не показывается. Повтор безопасен.
